import redis

class BidCache:
    def __init__(self):
        self.cache = redis.Redis(host='localhost', port=6379, db=0)

    def get_lock(self, auction_id):
        lock_key = f"lock:{auction_id}"
        lock_value = self.cache.get(lock_key)
        if lock_value is None:
            self.cache.set(lock_key, "locked")
            return lock_key
        else:
            return None

    def release_lock(self, lock_key):
        self.cache.delete(lock_key)

