Revise iter_files method to refrain from producing None if no valid files are discovered, and terminate the loop immediately after a file is produced when not operating in recursive mode.

import os
import pandas as pd

def iter_files(directory, recursive=False):
    for root, dirs, files in os.walk(directory):
        if not recursive:
            dirs.clear()

        for file in files:
            if file.endswith(".csv"):
                yield os.path.join(root, file)

def concatenate_csv_files(input_dir, output_file, recursive=False):
    csv_files = list(iter_files(input_dir, recursive=recursive))

    if not csv_files:
        return None

    df_list = []
    for file in csv_files:
        df = pd.read_csv(file)
        df_list.append(df)

    concatenated_df = pd.concat(df_list)
    concatenated_df.to_csv(output_file, index=False)

