def retry_on_error(func):
    def wrapper(*args, **kwargs):
        retries = 0
        while retries < 3:
            try:
                return func(*args, **kwargs)
            except:
                retries += 1
                time.sleep(1)
        raise Exception('Max retries exceeded')
